fn render_program(node: &ProgramTransport, w: &mut dyn ::sittir_core::render::RenderSink) -> ::sittir_core::render::RenderResult {
    let hash_bang_line = View::new(&node.hash_bang_line, "{}");
    let statements = ListView {
        items: node.statements.as_deref().unwrap_or(&[]),
        template: "{}",
        token: "",
        before: 0,
        after: node.statements_separator_space.unwrap_or(0),
        leading: false,
        trailing: false,
        head: Some(options::SITE_PROGRAM_STATEMENTS_START),
        tail: Some(options::SITE_PROGRAM_STATEMENTS_END),
    };
    w.edge(::sittir_core::types::KindId(188), ::sittir_core::options::Side::Before, node.layout.edges().before);
    hash_bang_line.render(w)?;
    ::sittir_core::trivia::render_inner(node.layout.trivia(), "statements", w)?;
    statements.render(w)?;
    w.edge(::sittir_core::types::KindId(188), ::sittir_core::options::Side::After, node.layout.edges().after);
    Ok(())
}

fn render_hash_bang_line(node: &HashBangLineTransport, w: &mut dyn ::sittir_core::render::RenderSink) -> ::sittir_core::render::RenderResult {
    let content = &node.content;
    w.text("#!")?;
    w.adjacent();
    content.render(w)?;
    Ok(())
}

