        w.site_at(options::SITE_EXPORT_STATEMENT_TYPE_EXPORT_FROM_KEYWORD_BEFORE);
        w.text("from")?;
        w.site_at(options::SITE_EXPORT_STATEMENT_TYPE_EXPORT_FROM_KEYWORD_AFTER);
